382	    /**
383	     * Return the Pet with the given name, or null if none found for this Owner.
384	     *
385	     * @param name to test
386	     * @return true if pet name is already in use
387	     */
388	    public Pet getPet(String name, boolean ignoreNew) {
389	        name = name.toLowerCase();
390	        for (Pet pet : getPetsInternal()) {
391	            if (!ignoreNew || !pet.isNew()) {
392	                String compName = pet.getName();
393	                compName = compName.toLowerCase();
394	                if (compName.equals(name)) {
395	                    return pet;
396	                }
397	            }
398	        }
399	        return null;
400	    }
401	
402	    public Pet getPet(Integer petId) {
403	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
404	    }
405	
406	    @Override
407	    public String toString() {
408	        return new ToStringCreator(this)
409	
410	            .append("id", this.getId())
411	            .append("new", this.isNew())
412	            .append("lastName", this.getLastName())
413	            .append("firstName", this.getFirstName())
414	            .append("address", this.address)
415	            .append("city", this.city)
416	            .append("telephone", this.telephone)
417	            .append("email", this.email)
418	            .toString();
419	    }
420	}
