37	import org.springframework.samples.petclinic.model.Pet;
38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
41	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.PetDto;
43	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
46	import org.springframework.samples.petclinic.service.ClinicService;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /** Dedicated audit trail for owner-lifecycle side effects. */
65	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    public OwnerRestControllerV1(ClinicService clinicService,
76	                                 OwnerMapper ownerMapper,
77	                                 PetMapper petMapper,
78	                                 VisitMapper visitMapper) {
79	        this.clinicService = clinicService;
80	        this.ownerMapper = ownerMapper;
81	        this.petMapper = petMapper;
82	        this.visitMapper = visitMapper;
83	    }
84	
85	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
86	    @Override
87	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
88	        Collection<Owner> owners;
89	        if (lastName != null) {
90	            owners = this.clinicService.findOwnerByLastName(lastName);
91	        } else {
92	            owners = this.clinicService.findAllOwners();
93	        }
94	        if (owners.isEmpty()) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
103	        Owner owner = this.clinicService.findOwnerById(ownerId);
104	        if (owner == null) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
113	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
114	        if (normalizedTelephone == null) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        String normalizedAddress = Owner.normalizeAddress(ownerFieldsDto.getAddress());
118	        if (normalizedAddress == null || normalizedAddress.isBlank()) {
119	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
120	        }
121	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
122	        owner.setTelephone(normalizedTelephone);
123	        if (!owner.isPostcodeValidForCity()) {
124	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
125	        }
126	        // Consolidated duplicate detection: all of the former separate telephone, email
127	        // and household checks are now expressed through the single derived identityKey
128	        // (telephone|email|householdId). Reject only when the new owner's WHOLE
129	        // identityKey equals an existing owner's. The household id is assigned later in
130	        // this method, so at this point the new owner's key carries an empty household
131	        // segment; two members of the same household with different telephones therefore
132	        // have different keys and are both allowed.
133	        String identityKey = owner.getIdentityKey();
134	        if (this.clinicService.findAllOwners().stream()
135	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()))) {
136	            return new ResponseEntity<>(HttpStatus.CONFLICT);
137	        }
138	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
139	            return new ResponseEntity<>(HttpStatus.CONFLICT);
140	        }
141	        LocalDate effectiveDate =
142	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
143	        LocalDate registrationDate = toBusinessDay(effectiveDate);
144	        long ownersRegisteredToday = countOwnersRegisteredOn(registrationDate);
145	        if (ownersRegisteredToday >= 100) {
146	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
147	        }
148	        boolean bulkSignupWarning = ownersRegisteredToday > 80;
149	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
150	        List<Owner> householdMembers =
151	            findHouseholdMembers(ownerFieldsDto.getLastName(), normalizedAddress);
152	        HttpHeaders headers = new HttpHeaders();
153	        owner.setRegistrationDate(registrationDate);
154	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
155	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
156	        owner.setBulkSignupWarning(bulkSignupWarning);
157	        if (sharesHousehold && !householdMembers.isEmpty()) {
158	            String householdId = householdId(owner.getLastName(), normalizedAddress);
159	            owner.setHouseholdId(householdId);
160	            owner.setHouseholdSize(householdMembers.size() + 1);
161	            for (Owner member : householdMembers) {
162	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
163	                    member.setHouseholdId(householdId);
164	                    this.clinicService.saveOwner(member);
165	                }
166	            }
167	        }
168	        this.clinicService.saveOwner(owner);
169	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
170	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
171	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
172	        headers.setLocation(UriComponentsBuilder.newInstance()
173	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
174	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
180	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
181	        if (currentOwner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
185	        if (normalizedTelephone == null) {
186	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
187	        }
188	        currentOwner.setAddress(ownerFieldsDto.getAddress());
189	        currentOwner.setCity(ownerFieldsDto.getCity());
190	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
191	        currentOwner.setLastName(ownerFieldsDto.getLastName());
192	        currentOwner.setTelephone(normalizedTelephone);
193	        currentOwner.setEmail(ownerFieldsDto.getEmail());
194	        this.clinicService.saveOwner(currentOwner);
195	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Transactional
200	    @Override
201	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
202	        Owner owner = this.clinicService.findOwnerById(ownerId);
203	        if (owner == null) {
204	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
205	        }
206	        this.clinicService.deleteOwner(owner);
207	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
213	        Owner owner = this.clinicService.findOwnerById(ownerId);
214	        if (owner == null) {
215	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	        }
217	        HttpHeaders headers = new HttpHeaders();
218	        Pet pet = petMapper.toPet(petFieldsDto);
219	        owner.setId(ownerId);
220	        pet.setOwner(owner);
221	        pet.getType().setName(null);
222	        this.clinicService.savePet(pet);
223	        PetDto petDto = petMapper.toPetDto(pet);
224	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
225	            .buildAndExpand(pet.getId()).toUri());
226	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
227	    }
228	
229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
232	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
233	        if (currentOwner != null) {
234	            Pet currentPet = this.clinicService.findPetById(petId);
235	            if (currentPet != null) {
236	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
237	                currentPet.setName(petFieldsDto.getName());
238	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
239	                this.clinicService.savePet(currentPet);
240	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
241	            }
242	        }
243	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
244	    }
245	
246	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
247	    @Override
248	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
249	        HttpHeaders headers = new HttpHeaders();
250	        Visit visit = visitMapper.toVisit(visitFieldsDto);
251	        Pet pet = new Pet();
252	        pet.setId(petId);
253	        visit.setPet(pet);
254	        this.clinicService.saveVisit(visit);
255	        VisitDto visitDto = visitMapper.toVisitDto(visit);
256	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
257	            .buildAndExpand(visit.getId()).toUri());
258	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
259	    }
260	
261	
262	    /**
263	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
264	     * stripped. When a leading {@code '+'} and country code are present they are kept;
265	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
266	     * is dropped from the national digits. The result must be a {@code '+'} followed
267	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
268	     * is returned to signal a bad request.
269	     */
270	    /**
271	     * Build the customer code for a newly created owner, formatted
272	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first
273	     * three letters of the city, {@code LAST3} the upper-cased first three letters of
274	     * the last name, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to
275	     * one more than the number of owners already in that city.
276	     */
277	    private String nextCustomerCode(String city, String lastName) {
278	        String cityPrefix = prefixThree(city);
279	        String lastNamePrefix = prefixThree(lastName);
280	        String normalizedCity = normalizeForHousehold(city);
281	        int sequence = (int) this.clinicService.findAllOwners().stream()
282	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
283	            .count() + 1;
284	        return String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence);
285	    }
286	
287	    /**
288	     * Count the existing owners whose city matches the given one, compared after
289	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
290	     * cap: a city that already holds this many owners is at capacity.
291	     */
292	    private long countOwnersInCity(String city) {
293	        String normalizedCity = normalizeForHousehold(city);
294	        return this.clinicService.findAllOwners().stream()
295	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
296	            .count();
297	    }
298	
299	    /**
300	     * Count the existing owners whose registration date falls on the given day. Used to
301	     * enforce the per-day create limit: once this many owners have been registered today,
302	     * the day is at capacity and further creates are rejected.
303	     */
304	    private long countOwnersRegisteredOn(LocalDate day) {
305	        return this.clinicService.findAllOwners().stream()
306	            .filter(existing -> day.equals(existing.getRegistrationDate()))
307	            .count();
308	    }
309	
310	    /**
311	     * Roll a registration date forward to the next business day: a date falling on a
312	     * Saturday or Sunday is advanced to the following Monday, while a weekday is
313	     * returned unchanged.
314	     */
315	    private LocalDate toBusinessDay(LocalDate date) {
316	        DayOfWeek dayOfWeek = date.getDayOfWeek();
317	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
318	            return date.plusDays(8 - dayOfWeek.getValue());
319	        }
320	        return date;
321	    }
322	
323	    /** Upper-cased first three letters of {@code value} (fewer if shorter, empty if null). */
324	    private String prefixThree(String value) {
325	        String v = value == null ? "" : value;
326	        return v.substring(0, Math.min(3, v.length())).toUpperCase(Locale.ROOT);
327	    }
328	
329	    /**
330	     * Find the existing owners that already belong to the same household as the given
331	     * last name and address, i.e. those sharing both fields. Both are compared
332	     * case-insensitively after collapsing runs of whitespace to a single space and
333	     * trimming the ends.
334	     */
335	    private List<Owner> findHouseholdMembers(String lastName, String address) {
336	        String normalizedLastName = normalizeForHousehold(lastName);
337	        String normalizedAddress = normalizeForHousehold(address);
338	        return this.clinicService.findAllOwners().stream()
339	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
340	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress))
341	            .toList();
342	    }
343	
344	    /**
345	     * Count the existing owners that already share both the given first and last
346	     * name, compared case-insensitively. Used to populate an owner's namesake count
347	     * at creation time, reflecting how many owners with the same name existed before
348	     * this one was created.
349	     */
350	    private int countNamesakes(String firstName, String lastName) {
351	        String normalizedFirstName = normalizeName(firstName);
352	        String normalizedLastName = normalizeName(lastName);
353	        return (int) this.clinicService.findAllOwners().stream()
354	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
355	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
356	            .count();
357	    }
358	
359	    private String normalizeName(String value) {
360	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
361	    }
362	
363	    /**
364	     * Build a stable identifier shared by all owners of one household. It is derived
365	     * deterministically from the normalized last name and address, so every owner at
366	     * the same household resolves to the same value regardless of creation order.
367	     */
368	    private String householdId(String lastName, String address) {
369	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
370	        try {
371	            byte[] digest = MessageDigest.getInstance("SHA-256")
372	                .digest(key.getBytes(StandardCharsets.UTF_8));
373	            StringBuilder sb = new StringBuilder();
374	            for (int i = 0; i < 6; i++) {
375	                sb.append(String.format("%02X", digest[i]));
376	            }
377	            return "HH-" + sb;
378	        }
379	        catch (NoSuchAlgorithmException e) {
380	            throw new IllegalStateException(e);
381	        }
382	    }
383	
384	    private String normalizeForHousehold(String value) {
385	        if (value == null) {
386	            return "";
387	        }
388	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
