        return null;
    }
    int sum = 0;
    boolean doubleDigit = true;
    for (int i = this.customerCode.length() - 1; i >= 0; i--) {
        char c = this.customerCode.charAt(i);
        if (c < '0' || c > '9') {
            continue;
        }
        int digit = c - '0';
        if (doubleDigit) {
            digit *= 2;
            if (digit > 9) {
                digit -= 9;
            }
        }
        sum += digit;
        doubleDigit = !doubleDigit;
    }
    return (10 - (sum % 10)) % 10;
